% Load input image and convert to grayscale
input_image = imread('image.jpg');
gray_image = rgb2gray(input_image);

% Set standard deviation for Gaussian filter
sigma = 3;

% Create Gaussian kernel
[gaussian_kernel, gaussian_kernel_size] = fspecial('gaussian', [5 5], sigma);

% Filter the input image with Gaussian kernel
filtered_image = imfilter(gray_image, gaussian_kernel, 'replicates');

% Define Sobel operators in x and y directions
sobel_x = [-1 0 1; -2 0 2; -1 0 1];
sobel_y = [-1 -2 -1; 0 0 0; 1 2 1];

% Apply Sobel operator in x direction
edge_image_x = conv2(double(filtered_image), sobel_x, 'same');

% Apply Sobel operator in y direction
edge_image_y = conv2(double(filtered_image), sobel_y, 'same');

% Combine edges in both directions and display result
edge_image = sqrt(edge_image_x.^2 + edge_image_y.^2);
imshow(edge_image);
```

