```typescript
import { createInjectable } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { NestMiddleware } from './middleware.interface';
import { LoggerService } from './logger.service';

@createInjectable()
export class DevelopmentOnlyMiddleware implements NestMiddleware {
  constructor(private logger: LoggerService) {}

  use(context: NestMiddlewareContext, next: () => Promise<any>) {
    const env = process.env.NODE_ENV;
    this.logger.log(`Executing ${this.constructor.name} in ${env}`);
    if (env === 'development') {
      return next().catch((err) => {
        this.logger.error('Caught error', err);
        throw err;
      });
    } else {
      this.logger.log(`Skipping ${this.constructor.name} in ${env}`);
      return false;
    }
  }
}

export function DevelopmentOnly(target: Object | Function) {
  Reflect.defineMetadata('developmentOnly', true, target, Reflect.MetadataKeys.DECORATOR);
  return DevelopmentOnlyMiddleware;
}

export interface NestMiddlewareContext {
  req: any;
  res: any;
  next(): Promise<any>;
}

export function useMiddleware(...middlewares: NestMiddleware[]) {
  return function (target: Object | Function) {
    Reflect.defineMetadata('middleware', [...Reflect.getMetadata('middleware', target), ...middlewares], target, Reflect.MetadataKeys.DECORATOR);
    return target;
  };
}

NestFactory.prototype.useGlobalMiddlewares = function (...middlewares: NestMiddleware[]) {
  Reflect.defineMetadata('middleware', [...Reflect.getMetadata('middleware', this.options), ...middlewares], this.options, Reflect.MetadataKeys.DECORATOR);
  return this;
};

