    const parts = line.replace(/^\s+|\s+$/, '').split(' ');

    // Determine whether the line is adding or removing something
    const operation = parts[0] === '+' ? 'push' : 'splice';
    const index = parts[1].slice(1, -1).split(',').map(str => str.trim()).reduce((acc, curr) => acc * 1 + curr * 1, 0);
