     getPrevData(prev, newQuery) {
       // Batch multiple queries together
       if (!prev || !newQuery.variables?.pageSize) {
         return prev;
       }
       if (prev && prev.pageInfo.hasNextPage && newQuery.variables.pageSize > prev.pageInfo.endCursor) {
         // Combine results with previous page
